const importFiles=async(files:FileList|File[])=>{if(uploading||exporting)return;const projectId=projectRef.current.id;for(const file of Array.from(files)){if(!/^(video|audio|image)\//.test(file.type)||file.type==='image/svg+xml'){toast.error(`Unsupported file: ${file.name}`);continue;}if(file.size>100*1024*1024){toast.error(`${file.name} exceeds 100 MB`);continue;}setUploading(file.name);const controller=new AbortController();abortUpload.current=controller;try{const info=await inspectFile(file);if(controller.signal.aborted)throw Error('Import cancelled');const id=uid();const r=await fetch(`/api/media?key=${encodeURIComponent(projectId+'/'+id)}`,{method:'POST',headers:{'content-type':file.type},body:file,signal:controller.signal});const data=await r.json() as ApiResponse;if(!r.ok)throw Error(data.error||'Request failed');if(projectRef.current.id!==projectId)throw Error('Project changed during upload');const asset:Asset={id,name:file.name,kind:file.type.startsWith('video/')?'video':file.type.startsWith('audio/')?'audio':'image',src:data.src,...info};commit(projectSchema.parse({...projectRef.current,assets:[...projectRef.current.assets,asset]}));setShowAssets(true);toast.success(`${file.name} added to Library`);}catch(e){toast.error(e instanceof Error?e.message:'Import failed');}finally{setUploading(undefined);abortUpload.current=undefined;}}if(fileRef.current)fileRef.current.value='';};
